mapper.update:
UPDATE TB_MEMBER
SET POST_COUNT = NVL(POST_COUNT, 0) + 1
WHERE MEMBER_ID = #{memberId}

mapper.select:
SELECT MEMBER_NO
FROM TB_MEMBER
WHERE MEMBER_ID = #{memberId}

SELECT MEMBER_NO
FROM TB_MEMBER
WHERE EMAIL = #{email}

mapper.update:
UPDATE TB_POST
SET TAGS = #{tags}
WHERE POST_ID = #{postId}
  AND BOARD_TYPE IN ('TOWN', 'LIFE', 'SHARE')

UPDATE TB_POST
SET TITLE = #{title},
    BODY  = #{body}
WHERE POST_ID = #{postId}
  AND MEMBER_NO = #{memberNo}
  AND BOARD_TYPE IN ('TOWN', 'LIFE', 'SHARE')
  AND NVL(STATUS_CD, 'ACTIVE') = 'ACTIVE'

mapper.delete:
DELETE FROM TB_POST
WHERE POST_ID = #{postId}
  AND MEMBER_NO = #{memberNo}
  AND NVL(STATUS_CD, 'ACTIVE') = 'ACTIVE'
  AND BOARD_TYPE IN ('TOWN', 'SHARE')

DELETE FROM TB_FILE
WHERE REF_TYPE = 'POST'
  AND REF_ID = #{postId}

DELETE FROM TB_FILE
 WHERE REF_TYPE = 'POST'
   AND REF_ID = #{postId}
   AND FILE_URL = #{fileUrl}

DELETE FROM TB_POST
WHERE POST_ID = #{postId}
  AND STATUS_CD = 'DELETED'
